INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES ('153', '24', '3', '3', 'calculation', '12', '求幂级数 \(\displaystyle\sum_{n=1}^\infty[1-n\ln(1+1/n)]x^n\) 的收敛域。', '\([-1,1)\)。', '系数 \(a_n\sim1/(2n)\)，故半径为 1。\(x=1\) 发散；\(x=-1\) 时由 Leibniz 判别法收敛。', '2021 年第十二届全国大学生数学竞赛决赛（非数学类） 求幂级数 ( n=1 [1-n (1+1/n)]x n ) 的收敛域。 ([-1,1) )。 系数 (a n 1/(2n) )，故半径为 1。 (x=1 ) 发散； (x=-1 ) 时由 Leibniz 判别法收敛。', '1', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES ('154', '24', '4', '4', 'proof', '12', '设 \(f\) 在 \([a,b]\) 连续、在 \((a,b)\) 二阶可导，且 \(f(a)=f(b)=0\)、\(\int_a^bf(x)dx=0\)。证明存在不同的 \(x_1,x_2\) 使 \(f''(x_i)=f(x_i)\)，并存在不同于二者的 \(\xi\) 使 \(f''''(\xi)=f(\xi)\)。', '所述 \(x_1,x_2,\xi\) 均存在。', '依次对 \(e^{-x}\int_a^xf\)、\(f(x)-\int_a^xf\) 和 \(e^x[f''(x)-f(x)]\) 使用 Rolle 定理。', '2021 年第十二届全国大学生数学竞赛决赛（非数学类） 设 (f ) 在 ([a,b] ) 连续、在 ((a,b) ) 二阶可导，且 (f(a)=f(b)=0 )、 ( a bf(x)dx=0 )。证明存在不同的 (x 1,x 2 ) 使 (f''(x i)=f(x i) )，并存在不同于二者的 ( ) 使 (f''''( )=f( ) )。 所述 (x 1,x 2, ) 均存在。 依次对 (e -x a xf )、 (f(x)- a xf ) 和 (e x[f''(x)-f(x)] ) 使用 Rolle 定理。', '1', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES ('155', '24', '5', '5', 'comprehensive', '12', '设 \(A\) 是 \(n\) 阶实对称矩阵。证明存在唯一实对称矩阵 \(B\)，使 \(B^{2021}=A\)、\(AB=BA\)，且存在多项式 \(p\) 使 \(B=p(A)\)。', '所述实对称奇次方根存在、可表示为 \(p(A)\)，且唯一。', '正交对角化 \(A\)，对每个实特征值取唯一实 2021 次根构造 \(B\)；用 Lagrange 插值构造 \(p\)。标量奇次根唯一给出矩阵解唯一。', '2021 年第十二届全国大学生数学竞赛决赛（非数学类） 设 (A ) 是 (n ) 阶实对称矩阵。证明存在唯一实对称矩阵 (B )，使 (B 2021 =A )、 (AB=BA )，且存在多项式 (p ) 使 (B=p(A) )。 所述实对称奇次方根存在、可表示为 (p(A) )，且唯一。 正交对角化 (A )，对每个实特征值取唯一实 2021 次根构造 (B )；用 Lagrange 插值构造 (p )。标量奇次根唯一给出矩阵解唯一。', '1', 'published') ON CONFLICT (id) DO NOTHING;
